sketches.source:
setcpm(66/4)

// Meltwater: drips off the ice and a stream finding its way
drips: s("drip*8?0.6").pan(rand).gain(rand.range(.05, .15)).space("outdoor")
stream: s("stream").slow(4).intensity(.3).distance(3).gain(.2)

// The first geese returning, far overhead
geese: s("bird").slow(4).azimuth(saw.range(-120, 120).slow(8)).elevation(40).distance(8).posglide(.4).gain(.18)

// Glassy chords opening over the snow: D, A, E, D with the raised fourth
chords: note("<[d3,a3,e4] [a2,e3,c#4] [e2,b2,g#3] [d3,a3,g#4]>").slow(2)
  .s("triangle").timbre("glass").attack(1).release(3).room(.7).size(.9).gain(.18)

// A few bright notes, like light on the melting ice
melody: n("<[4 ~ 5 ~] [~ 3 ~ ~] [2 ~ ~ 4] [~ ~ 3 ~]>").scale("D:lydian").transpose(12)
  .s("sine").fm(2).fmh(4).decay(1).sustain(0).release(1.5)
  .delay(.3).delaytime(3/8).room(.6).gain(.16)

setcpm(60/4)

// A rising wind across the open land
wind: s("wind").slow(8).intensity(.45).gain(.16)

// Cranes leaving, crossing the sky from one side to the other
cranes: s("bird").slow(5).azimuth(saw.range(0, 180).slow(16)).elevation(30).distance(9).posglide(.5).gain(.16)

// A choir on slow chords: Am, F, Dm, E
choir: note("<[a2,e3,c4] [f2,c3,a3] [d3,f3,a3] [e2,b2,g#3]>").slow(2)
  .s("choir").syl("<oo ah oo oh>")
  .attack(2).release(3).space("hall").gain(.24)

// Footsteps crunching on frozen moss
crunch: s("step ~ step ~").lpf(2000).gain(.12)

// Cold, far-off bells
bells: note("<e5 ~ c5 ~ a4 ~ ~ ~>").s("sine").fm(3).fmh(2.76)
  .decay(3).sustain(0).release(3).room(.8).gain(.1)

setcpm(96/4)

// Eight cycles: heat (1-2), gathering clouds (3-4), the storm (5-7), clearing (8)
insects: s("insect").slow(4).gain(.12)

// The wind builds with the clouds and dies away
wind: s("pink").hpf(200).lpf(sine.range(400, 2000).slow(8))
  .gain("<.03 .04 .08 .14 .22 .25 .15 .05>").pan(sine.slow(3))

// Thunder rolls closer, then the rain comes down
thunder: s("<~ ~ ~ [~ lt] ~ [lt ~ ~ lt] lt ~>").speed(.5).lpf(300).room(.9).size(.95).gain(.5)
rain: s("rain").intensity(.6).mask("<0 0 0 0 1 1 1 0>").gain(.3)

// A pad that darkens and opens with the storm: Em, C, Am, B
pad: note("<[e3,b3,d4] [e3,b3,d4] [c3,g3,b3] [c3,g3,b3] [a2,e3,c4] [a2,e3,c4] [b2,f#3,a3] [e3,b3,d4]>")
  .s("sawtooth").unison(3).detune(.2)
  .lpf(sine.range(600, 2400).slow(8)).attack(.5).release(1.5).room(.6).gain(.16)

// Drums arrive with the clouds and leave with the storm
drums: s("bd ~ ~ bd ~ ~ bd ~, ~ ~ sd ~").mask("<0 0 1 1 1 1 1 0>").gain(.45)

setcpm(64/4)

// A hard wind and blowing snow
wind: s("wind").slow(8).intensity(.6).gain(.18)
snow: s("white").slow(8).hpf(4000).lpf(8000).pan(sine.slow(6)).gain(.02)

// Overtone singing over the open steppe
throat: note("a1").slow(8).s("hum").overtone(8).gain(.22)

// A horse-head fiddle, long and reedy
fiddle: note("<[e3@3 d3] [e3@2 a3 g3] [e3@3 d3] [a2@4]>")
  .s("sawtooth").timbre("reed").vib(5).vibdepth(.15).lpf(1600)
  .attack(.1).sustain(.7).release(.5).room(.5).gain(.18)

// A horse trotting through the snow
hooves: s("lt [~ lt] lt [~ lt]").speed(.8).lpf(500).distance(4).gain(.2)

setcpm(104/4)

// Birds high in the flowering canopy, parrots crossing overhead
birds: s("bird").slow(2).azimuth(-60).elevation(30).distance(4).gain(.24)
parrots: s("bird").slow(3).azimuth(saw.range(20, 160).slow(8)).elevation(40).distance(6).posglide(.3).gain(.2)

// Frogs clicking in the leaf litter
frogs: s("click*8?0.5").speed(.6).lpf(1500).pan(rand).gain(.1)

// A bright marimba through G, C, D, G
marimba: n("0 2 4 [7 4] 2 4 [0 2] ~").add("<0 3 4 0>").scale("G:major").transpose(12)
  .s("sine").fm(.6).fmh(4).decay(.35).sustain(0).room(.4).gain(.24)
pad: note("<[g3,b3,d4] [c4,e4,g4] [d4,f#4,a4] [g3,b3,d4]>")
  .s("sawtooth").unison(3).detune(.2).lpf(1500).attack(.5).release(1.5).room(.6).gain(.12)

// Hand drums
perc: s("lt ~ [~ lt] mt, ~ rim ~ rim").room(.3).gain(.35)
